SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.admittime, d.dischtime, d.deathtime, d.admission_type, d.admit_provider_id, d.admission_location, d.discharge_location, d.insurance, d.language, d.marital_status, d.race, d.edregtime, d.edouttime, d.hospital_expire_flag, pr.icd_code, pr.icd_version, COUNT(*) AS procedure_count, percentile_cont(0.25) within GROUP (ORDER BY COUNT(*)) AS p25, percentile_cont(0.75) within GROUP (ORDER BY COUNT(*)) AS p75 FROM patients p JOIN admissions d ON p.subject_id = d.subject_id JOIN procedures_icd pr ON d.subject_id = pr.subject_id AND d.hadm_id = pr.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 64 AND p.anchor_year = 2019 AND p.anchor_year_group = 'ACS' AND EXTRACT(YEAR FROM d.admittime) BETWEEN 2019 AND 2020 AND EXTRACT(YEAR FROM d.dischtime) BETWEEN 2019 AND 2020 AND d.deathtime IS NULL AND d.admission_type = 'ACUTE' AND d.admit_provider_id = 10000 AND d.admission_location = 'MICU' AND d.discharge_location = 'MICU' AND d.insurance = 'Private' AND d.language = 'English' AND d.marital_status = 'Single' AND d.race = 'White' AND d.edregtime BETWEEN 0 AND 1000 AND d.edouttime BETWEEN 0 AND 1000 AND d.hospital_expire_flag = 'N' AND EXTRACT(DAY FROM (d.dischtime - d.admittime)) BETWEEN 1 AND 3 AND pr.icd_code IN (SELECT icd_code FROM diagnoses_icd WHERE seq_num = 1) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.admittime, d.dischtime, d.deathtime, d.admission_type, d.admit_provider_id, d.admission_location, d.discharge_location, d.insurance, d.language, d.marital_status, d.race, d.edregtime, d.edouttime, d.hospital_expire_flag, pr.icd_code, pr.icd_version ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.admittime, d.dischtime, d.deathtime, d.admission_type, d.admit_provider_id, d.admission_location, d.discharge_location, d.insurance, d.language, d.marital_status, d.race, d.edregtime, d.edouttime, d.hospital_expire_flag, pr.icd_code, pr.icd_version NULLS LAST;